function escapeForJS(s) {
  return String(s)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\n/g, ' ')
    .replace(/\r/g, '');
}

function buildBlock(translations) {
  return Object.keys(translations).map((k) => {
    return '      ' + k + ": '" + escapeForJS(translations[k]) + "',";
  }).join('\n');
}

let out = src;
console.log('Processing languages:', Object.keys(ALL_TR).join(', '));
let totalInserted = 0;
for (const code of Object.keys(ALL_TR)) {
  const translations = ALL_TR[code];
  // Find this language's block in the source
  const langBlocks = [];
  const langRe = /^\s*(en|es|pt|fr|de|it|nl|pl|ja|ko|ru|tr|zh|id|vi|sv):\s*\{/gm;
  let m;
  while ((m = langRe.exec(out)) !== null) {
    langBlocks.push({ code: m[1], start: m.index });
  }
  for (let i = 0; i < langBlocks.length; i++) {
    langBlocks[i].end = (i + 1 < langBlocks.length) ? langBlocks[i + 1].start : out.length;
  }
  const lang = langBlocks.find((b) => b.code === code);
  if (!lang) { console.error('No block for', code); continue; }
  // Find err_network within this block
  const blockText = out.substring(lang.start, lang.end);
  const errMatch = blockText.match(/(\n\s+)err_network:\s*'([^']+)'/);
  if (!errMatch) { console.error('No err_network in', code); continue; }

  // Filter translations: only include keys that DON'T already exist in this block
  const missingKeys = Object.keys(translations).filter((k) => {
    // Check if the key already appears in the block (regex match for the key followed by colon)
    const re = new RegExp("^\\s+" + k + ":\\s", "m");
    return !re.test(blockText);
  });
  if (missingKeys.length === 0) {
    continue;
  }
  const block = missingKeys.map((k) =>
    '      ' + k + ": '" + escapeForJS(translations[k]) + "',"
  ).join('\n');
  const errAbsPos = lang.start + errMatch.index;
  const insertion = '\n      // === 2026-08-26 translations added to fill i18n gaps ===\n' + block + '\n';
  out = out.substring(0, errAbsPos) + insertion + out.substring(errAbsPos);
  console.log('  ' + code + ': inserted ' + missingKeys.length + ' keys');
  totalInserted += missingKeys.length;
}
console.log('Total keys inserted across all languages: ' + totalInserted);

fs.writeFileSync(I18N_PATH, out);
console.log('Done. Updated 12 language blocks with missing keys.');
